/**
 * @name Ancient Egypt Night
 * @author You
 * @version 1.0.0
 * @description Egyptian gold, lapis-blue and obsidian theme for BetterDiscord. All artwork is embedded - no internet hosting needed.
 * @source -
 */

@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;700&family=Rajdhani:wght@500;600;700&family=Cairo:wght@500;700&display=swap');

/* ============================================================
   1. EMBEDDED ARTWORK
   ============================================================ */
:root {
  --eg-bg:        url("data:image/webp;base64,");
  --eg-bust:      url("data:image/webp;base64,");
  --eg-anubis:    url("data:image/webp;base64,");
  --eg-pharaoh:   url("data:image/webp;base64,");
  --eg-divider:   url("data:image/webp;base64,");
  --eg-ankh:      url("data:image/webp;base64,");
  --eg-gem:       url("data:image/webp;base64,");
}

/* ============================================================
   2. PALETTE  (edit these to re-colour everything)
   ============================================================ */
:root {
  --eg-gold:      #e6b13f;
  --eg-gold-hi:   #ffd97a;
  --eg-gold-lo:   #7a5314;
  --eg-ink:       #06070b;
  --eg-panel:     rgba(7, 9, 15, .90);
  --eg-panel-2:   rgba(14, 17, 27, .82);
  --eg-lapis:     #2fb6ff;
  --eg-violet:    #9b4dff;
  --eg-ember:     #ff8a1f;
  --eg-text:      #f2e6c9;
  --eg-muted:     #b39a62;
  --eg-frame-x:   6px;    /* side margin */
  --eg-frame-b:   40px;   /* bottom hieroglyph strip    */
  --eg-frame-t:   48px;   /* top bar height             */
  --eg-top-strip: url("data:image/webp;base64,");
  --eg-logo: url("data:image/webp;base64,");
  --eg-stone: url("data:image/webp;base64,");
  --eg-orn-tl: url("data:image/webp;base64,");
  --eg-orn-tr: url("data:image/webp;base64,");
  --eg-orn-bl: url("data:image/webp;base64,");
  --eg-orn-br: url("data:image/webp;base64,");
  --eg-bottom-scarab: url("data:image/webp;base64,");
  --eg-panel-h:    84px;   /* reserved height of the floating user panel */
  --eg-cyan-glow:  rgba(47,182,255,.20);
  --eg-stone-text: #a9c9f2;
  --eg-card-bg:    linear-gradient(180deg, rgba(8,11,18,.97), rgba(4,5,9,.98));
  --eg-font-ui:   'Rajdhani', 'Cairo', 'gg sans', sans-serif;
  --eg-font-head: 'Rajdhani', 'Cairo', 'gg sans', sans-serif;
}

/* Discord colour tokens (old + new naming) */
.theme-dark, .theme-darker, .theme-midnight, .theme-light, :root {
  --background-primary: #0a0c13;
  --background-secondary: #080a10;
  --background-secondary-alt: #06070b;
  --background-tertiary: #05060a;
  --background-floating: #0b0d15;
  --background-accent: #1a1608;
  --background-modifier-hover: rgba(230,177,63,.10);
  --background-modifier-selected: rgba(47,182,255,.14);
  --background-modifier-active: rgba(230,177,63,.18);
  --background-modifier-accent: rgba(230,177,63,.22);
  --background-base-lowest: #05060a;
  --background-base-lower: #070910;
  --background-base-low: #0a0c13;
  --background-surface-high: #0d1018;
  --background-surface-higher: #121520;
  --background-surface-highest: #171b28;
  --background-mod-subtle: rgba(230,177,63,.07);
  --background-mod-normal: rgba(230,177,63,.12);
  --background-mod-strong: rgba(230,177,63,.20);
  --chat-background-default: transparent;
  --channeltextarea-background: rgba(5,6,10,.88);
  --text-normal: var(--eg-text);
  --text-default: var(--eg-text);
  --text-strong: #fff3d6;
  --text-muted: var(--eg-muted);
  --text-secondary: var(--eg-muted);
  --text-link: var(--eg-lapis);
  --header-primary: var(--eg-gold-hi);
  --header-secondary: var(--eg-muted);
  --channels-default: #cdb579;
  --interactive-normal: #c9a95a;
  --interactive-hover: var(--eg-gold-hi);
  --interactive-active: #fff;
  --interactive-muted: #5e4c25;
  --interactive-icon-default: #c9a95a;
  --interactive-icon-hover: var(--eg-gold-hi);
  --brand-500: #c78b1f;
  --brand-530: #d89a24;
  --brand-560: #b57a14;
  --brand-600: #9a650d;
  --brand-experiment: #c78b1f;
  --brand-experiment-560: #b57a14;
  --scrollbar-thin-thumb: var(--eg-gold-lo);
  --scrollbar-thin-track: transparent;
  --scrollbar-auto-thumb: var(--eg-gold-lo);
  --scrollbar-auto-track: transparent;
  --font-primary: var(--eg-font-ui);
  --font-display: var(--eg-font-head);
}

/* ============================================================
   3. WINDOW  (dark hieroglyph backdrop - NO thick frame; panels are cards)
   ============================================================ */
html, body { background: #04050a !important; font-family: var(--eg-font-ui); }

#app-mount {
  position: fixed !important;
  top: 0; left: var(--eg-frame-x); right: var(--eg-frame-x); bottom: var(--eg-frame-b);
  width: auto !important; height: auto !important;
}

/* faint hieroglyph strips behind the title bar and under the app */
body::before {
  content: ""; position: fixed; inset: 0; z-index: 0; pointer-events: none;
  background:
    var(--eg-top-strip) 0 0 / auto var(--eg-frame-t) repeat-x,
    var(--eg-bottom-scarab) 50% 100% / auto var(--eg-frame-b) no-repeat,
    var(--eg-top-strip) 0 100% / auto var(--eg-frame-b) repeat-x;
  opacity: 1;
}
/* winged scarab plaque, top centre (window buttons stay clickable) */
body::after {
  content: ""; position: fixed; top: 0; left: 0; right: 0; height: 56px; z-index: 99999; pointer-events: none;
  background: var(--eg-logo) 50% 0 / auto 56px no-repeat;
}

/* title bar: transparent so the strip shows through */
[class*="titleBar_"], [class*="typeWindows_"], [class*="bar_"][class*="titleBar"] {
  background: transparent !important;
  height: var(--eg-frame-t) !important;
}
[class*="titleBar_"] [class*="wordmark_"] { display: none; }

/* ============================================================
   4. SERVER LIST
   ============================================================ */
[class*="guilds_"], nav[class*="wrapper_"][aria-label*="Servers"], [class*="wrapper_"][class*="guilds"] {
  background: linear-gradient(180deg, #07090f, #04050a) !important;
  border: none !important;
  box-shadow: none !important;
}
/* server icons: round, gold ring */
[data-list-item-id^="guildsnav___"] [class*="childWrapper_"],
[data-list-item-id^="guildsnav___"] [class*="icon_"] {
  border-radius: 50% !important;
  border: 2px solid var(--eg-gold) !important;
  box-shadow: 0 0 10px rgba(230,177,63,.35), inset 0 0 8px rgba(0,0,0,.7);
  background-color: #0b0d15 !important;
  transition: box-shadow .15s ease, border-color .15s ease;
}
[data-list-item-id^="guildsnav___"]:hover [class*="childWrapper_"] {
  border-color: var(--eg-gold-hi) !important;
  box-shadow: 0 0 16px rgba(255,217,122,.65), inset 0 0 8px rgba(0,0,0,.6);
}
/* Home button -> pharaoh emblem (taller, like the mockup) */
[data-list-item-id="guildsnav___home"] [class*="childWrapper_"] {
  width: 64px !important; height: 80px !important;
  background: var(--eg-pharaoh) center / contain no-repeat !important;
  border: none !important; box-shadow: 0 0 18px rgba(47,182,255,.45) !important;
  border-radius: 0 !important;
}
[data-list-item-id="guildsnav___home"] svg { opacity: 0 !important; }
[class*="pill_"] [class*="item_"], [class*="pill_"] span[class*="item_"] { background: var(--eg-gold) !important; }

/* ============================================================
   5. CHANNEL SIDEBAR  (framed card)
   ============================================================ */
[class*="sidebar_"] {
  position: relative;
  background: var(--eg-card-bg) !important;
  border: 1px solid var(--eg-gold) !important;
  border-radius: 8px 8px 0 0;
  margin-left: 2px;
  box-shadow: 0 0 0 1px #000, inset 0 0 26px var(--eg-cyan-glow), 0 0 14px rgba(230,177,63,.14);
}
[class*="sidebar_"] > nav, [class*="sidebar_"] [class*="scroller_"] { background: transparent !important; }

/* Ankh pinned between the channel list and the user panel */
[class*="sidebar_"]::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: calc(var(--eg-panel-h) - 6px); height: 72px;
  background: var(--eg-ankh) center bottom / contain no-repeat;
  pointer-events: none; z-index: 1; opacity: .95;
  filter: drop-shadow(0 0 8px rgba(155,77,255,.45));
}
[class*="sidebar_"] [class*="scroller_"] { padding-bottom: 76px !important; }

/* Server header = its own gold card + winged scarab divider under it */
[class*="sidebar_"] header[class*="header_"], [class*="sidebar_"] [class*="headerContent_"] {
  font-family: var(--eg-font-head); font-weight: 700; font-size: 1.1rem; color: var(--eg-gold-hi);
}
[class*="sidebar_"] header[class*="header_"] {
  position: relative; margin: 6px 6px 26px; border-radius: 8px;
  border: 1px solid var(--eg-gold) !important;
  background:
    var(--eg-orn-tl) 0 0 / 40px auto no-repeat,
    var(--eg-orn-tr) 100% 0 / 40px auto no-repeat,
    var(--eg-orn-bl) 0 100% / 40px auto no-repeat,
    var(--eg-orn-br) 100% 100% / 40px auto no-repeat,
    linear-gradient(180deg, #080b12, #04050a) !important;
  box-shadow: 0 0 0 1px #000, 0 0 12px rgba(230,177,63,.22), inset 0 0 14px var(--eg-cyan-glow) !important;
}
[class*="sidebar_"] header[class*="header_"]::after {
  content: ""; position: absolute; left: 8px; right: 8px; bottom: -22px; height: 24px;
  background: var(--eg-gem) center / contain no-repeat; pointer-events: none; z-index: 3;
}

/* Categories = rounded gold-outline pills */
[class*="containerDefault_"] [class*="wrapper_"]:has(> [class*="mainContent_"]) {
  border: 1px solid var(--eg-gold) !important; border-radius: 8px !important;
  background: linear-gradient(180deg, rgba(10,13,21,.96), rgba(4,5,9,.96)) !important;
  box-shadow: 0 0 0 1px #000, inset 0 0 10px rgba(230,177,63,.10);
  margin: 10px 4px 4px; padding-inline: 6px; min-height: 34px;
}
[class*="containerDefault_"] [class*="mainContent_"], [class*="containerDefault_"] h3, h3[class*="name_"][class*="category"] {
  font-family: var(--eg-font-head) !important; font-weight: 700 !important; font-size: 1.05rem !important;
  color: var(--eg-gold-hi) !important; letter-spacing: 0; text-transform: none !important;
}

/* Channel rows = dark carved-stone tiles */
[class*="containerDefault_"] [class*="interactive_"] {
  border-radius: 6px !important;
  border: 1px solid rgba(120,170,255,.16);
  background:
    var(--eg-stone) 0 0 / 70px auto repeat,
    linear-gradient(90deg, rgba(24,34,54,.55), rgba(11,16,27,.55)) !important;
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.55);
  margin-block: 3px;
  transition: border-color .15s ease, box-shadow .15s ease;
}
[class*="containerDefault_"] [class*="interactive_"]:hover {
  border-color: rgba(255,217,122,.6);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.55), 0 0 12px rgba(230,177,63,.25);
}
[class*="containerDefault_"] [class*="icon_"] { color: #f0b030 !important; }
[class*="containerDefault_"] [class*="name_"], [class*="containerDefault_"] a { color: var(--eg-stone-text); font-weight: 600; font-size: 1.06rem; }
[class*="modeSelected_"] {
  border-color: var(--eg-lapis) !important;
  box-shadow: inset 0 0 14px rgba(47,182,255,.30), 0 0 14px rgba(47,182,255,.35), inset -26px 0 24px -18px rgba(47,182,255,.55) !important;
}
[class*="modeSelected_"] [class*="name_"] { color: #fff !important; }

/* User panel (bottom-left) - Discord floats it, so no position override */
[class*="panels_"] {
  background: linear-gradient(180deg, #080a11, #04050a) !important;
  border: 1px solid var(--eg-gold) !important; border-radius: 8px !important;
  box-shadow: 0 0 0 1px #000, 0 -6px 20px rgba(0,0,0,.6), inset 0 0 18px var(--eg-cyan-glow);
  z-index: 4;
}
[class*="panels_"] [class*="avatarWrapper_"] img, [class*="panels_"] [class*="avatar_"] { border-radius: 50% !important; }
[class*="panels_"] [class*="avatarWrapper_"] { box-shadow: 0 0 0 2px var(--eg-gold), 0 0 14px rgba(47,182,255,.5); border-radius: 50%; }

/* ============================================================
   6. CHAT AREA
   ============================================================ */
[class*="chat_"] {
  position: relative;
  background:
    linear-gradient(180deg, rgba(3,4,8,.72) 0%, rgba(3,4,8,.50) 45%, rgba(3,4,8,.74) 100%),
    var(--eg-bg) center / cover no-repeat !important;
  border: 1px solid var(--eg-gold);
  border-radius: 8px;
  box-shadow: 0 0 0 1px #000, inset 0 0 30px var(--eg-cyan-glow), 0 0 14px rgba(230,177,63,.12);
  overflow: hidden;
}
[class*="chatContent_"], [class*="messagesWrapper_"], [class*="scrollerBase_"][class*="scroller"], [class*="content_"][class*="flex"] {
  background: transparent !important;
}

/* Pharaoh bust: cropped at the right edge, fading into the scene */
[class*="chatContent_"]::after {
  content: ""; position: absolute; right: -70px; bottom: 56px; width: 330px; height: 80%;
  background: var(--eg-bust) right bottom / contain no-repeat;
  opacity: .82; pointer-events: none; z-index: 0;
  filter: drop-shadow(0 0 22px rgba(47,182,255,.30));
  -webkit-mask-image: linear-gradient(90deg, transparent 0, #000 38%);
          mask-image: linear-gradient(90deg, transparent 0, #000 38%);
}
[class*="messagesWrapper_"], [class*="channelTextArea_"], [class*="chatContent_"] > form { position: relative; z-index: 1; }

/* Header bar */
[class*="chat_"] section[class*="title_"] {
  background: linear-gradient(180deg, rgba(5,6,10,.96), rgba(8,10,16,.92)) !important;
  border-bottom: 1px solid var(--eg-gold) !important;
  box-shadow: 0 4px 18px rgba(0,0,0,.55);
  position: relative; z-index: 3;
}
[class*="chat_"] section[class*="title_"] h1, [class*="chat_"] section[class*="title_"] [class*="title_"] {
  font-family: var(--eg-font-head); color: #fff; font-weight: 700;
}
[class*="chat_"] section[class*="title_"] [class*="topic_"], [class*="chat_"] section[class*="title_"] [class*="topic"] { color: var(--eg-gold-hi) !important; }
[class*="chat_"] section[class*="title_"] [class*="icon_"], [class*="toolbar_"] svg { color: var(--eg-lapis) !important; }

/* Messages */
[class*="messageListItem_"] { text-shadow: 0 1px 3px rgba(0,0,0,.95); }
[class*="message_"]:hover { background: rgba(230,177,63,.05) !important; }
[class*="markup_"] { color: #efe8d6; font-weight: 600; font-size: 1.06rem; }
[class*="timestamp_"] time, time[class*="timestamp_"] { color: #d9a63f !important; font-size: .8rem; }
[class*="messageContent_"] { font-family: var(--eg-font-ui); }
[class*="avatar_"][class*="clickable"], [class*="message_"] img[class*="avatar_"] {
  border-radius: 6px !important; box-shadow: 0 0 0 2px var(--eg-gold), 0 0 10px rgba(230,177,63,.35);
}
[class*="message_"] [class*="username_"] { font-weight: 700; letter-spacing: .01em; color: var(--eg-gold-hi) !important; }

/* Date dividers with wings */
[class*="divider_"][class*="hasContent_"], [class*="divider_"][class*="isUnread_"] {
  border: none !important; height: 44px; margin: 14px 16px;
  background: var(--eg-divider) center / auto 44px no-repeat !important;
  display: flex; align-items: center; justify-content: center;
}
[class*="divider_"][class*="hasContent_"]::before, [class*="divider_"][class*="hasContent_"]::after { display: none !important; }
[class*="divider_"][class*="hasContent_"] > span, [class*="divider_"][class*="hasContent_"] [class*="content_"] {
  background: rgba(6,7,12,.96) !important; color: var(--eg-gold-hi) !important;
  border: 1px solid var(--eg-gold); border-radius: 20px;
  padding: 3px 18px; font-family: var(--eg-font-head); font-weight: 700; font-size: .9rem;
  box-shadow: 0 0 12px rgba(230,177,63,.35);
}

/* Message box: gold card with ornate corners */
[class*="channelTextArea_"] { background: transparent !important; margin: 0 14px 14px; }
[class*="channelTextArea_"] [class*="scrollableContainer_"] {
  background:
    var(--eg-orn-tl) 0 0 / 44px auto no-repeat,
    var(--eg-orn-tr) 100% 0 / 44px auto no-repeat,
    var(--eg-orn-bl) 0 100% / 44px auto no-repeat,
    var(--eg-orn-br) 100% 100% / 44px auto no-repeat,
    linear-gradient(180deg, rgba(8,10,16,.94), rgba(4,5,9,.97)) !important;
  border: 1px solid var(--eg-gold) !important; border-radius: 6px !important;
  box-shadow: 0 0 0 1px #000, 0 0 18px rgba(230,177,63,.28), inset 0 0 14px rgba(47,182,255,.08);
}
[class*="channelTextArea_"] [class*="textArea_"], [class*="slateTextArea_"] { color: var(--eg-text); font-weight: 600; }
[class*="channelTextArea_"] [class*="placeholder_"] { color: #8f7a48 !important; font-weight: 600; }
[class*="channelTextArea_"] svg { color: var(--eg-gold); }

/* ============================================================
   7. MEMBER LIST
   ============================================================ */
[class*="membersWrap_"] {
  position: relative;
  background: var(--eg-card-bg) !important;
  border: 1px solid var(--eg-gold);
  border-radius: 8px;
  margin-right: 2px;
  box-shadow: 0 0 0 1px #000, inset 0 0 26px var(--eg-cyan-glow), 0 0 14px rgba(230,177,63,.12);
}
[class*="members_"] { background: transparent !important; }

/* Anubis guarding the bottom of the list */
[class*="membersWrap_"]::after {
  content: ""; position: absolute; right: -10px; bottom: 0; width: 210px; height: 300px;
  background: var(--eg-anubis) right bottom / contain no-repeat;
  opacity: .88; pointer-events: none; z-index: 0;
  filter: drop-shadow(0 0 14px rgba(155,77,255,.5));
}
[class*="members_"] [class*="content_"] { position: relative; z-index: 1; }

h3[class*="membersGroup_"], [class*="members_"] h3 {
  font-family: var(--eg-font-head) !important; font-weight: 700 !important;
  color: var(--eg-gold-hi) !important; text-transform: none !important; letter-spacing: 0;
  font-size: 1.05rem !important;
  border-bottom: 1px solid transparent;
  border-image: linear-gradient(90deg, var(--eg-gold), transparent) 1;
  padding-bottom: 4px; margin-top: 10px;
}
[class*="members_"] [class*="member_"] {
  border: 1px solid rgba(120,170,255,.10); border-radius: 6px !important;
  background: linear-gradient(90deg, rgba(14,19,30,.80), rgba(6,8,14,.55)) !important;
  margin-block: 3px;
}
[class*="members_"] [class*="member_"]:hover { border-color: rgba(255,217,122,.55); box-shadow: 0 0 12px rgba(230,177,63,.22); }
[class*="members_"] [class*="member_"] img[class*="avatar"] { border-radius: 50% !important; }
[class*="members_"] [class*="roleIcon_"] { filter: drop-shadow(0 0 4px rgba(255,217,122,.6)); }
[class*="members_"] [class*="subText_"], [class*="members_"] [class*="activity_"] { color: #c9bfa0 !important; font-weight: 600; }

/* Search box: framed card */
[class*="search_"] [class*="searchBar_"], [class*="searchBar_"] {
  background:
    var(--eg-orn-tl) 0 0 / 30px auto no-repeat, var(--eg-orn-tr) 100% 0 / 30px auto no-repeat,
    var(--eg-orn-bl) 0 100% / 30px auto no-repeat, var(--eg-orn-br) 100% 100% / 30px auto no-repeat,
    rgba(5,6,10,.92) !important; border: 1px solid var(--eg-gold); border-radius: 8px;
  box-shadow: 0 0 0 1px #000, 0 0 12px rgba(230,177,63,.22), inset 0 0 10px var(--eg-cyan-glow);
}
[class*="searchBar_"] svg { color: var(--eg-lapis) !important; }

/* ============================================================
   8. POPOUTS / MODALS / MENUS / SETTINGS
   ============================================================ */
[class*="layer_"] [class*="popout_"], [class*="layer_"] > [class*="menu_"], [class*="layer_"] [class*="contextMenu"] {
  background: linear-gradient(180deg, #0c0e17, #06070c) !important;
  border: 1px solid var(--eg-gold) !important;
  box-shadow: 0 0 0 1px #000, 0 10px 40px rgba(0,0,0,.8), 0 0 22px rgba(230,177,63,.25) !important;
  border-radius: 6px !important;
}
[class*="menu_"] [class*="focused_"], [class*="item_"][class*="focused_"] { background: rgba(230,177,63,.16) !important; color: var(--eg-gold-hi) !important; }

[class*="modal_"], [class*="root_"][class*="modal"] {
  background: linear-gradient(180deg, #0b0d16, #05060a) !important;
  border: 1px solid var(--eg-gold) !important;
  box-shadow: 0 0 0 1px #000, 0 20px 70px rgba(0,0,0,.85), 0 0 30px rgba(230,177,63,.25) !important;
}
[class*="header_"][class*="modal"], [class*="modal_"] h1, [class*="modal_"] h2 { font-family: var(--eg-font-head); color: var(--eg-gold-hi); }

/* User settings */
[class*="standardSidebarView_"], [class*="contentRegion_"], [class*="contentRegionScroller_"], [class*="sidebarRegion_"], [class*="contentColumn_"] {
  background: linear-gradient(180deg, #080a10, #05060a) !important;
}
[class*="sidebarRegion_"] { border-right: 1px solid rgba(230,177,63,.35); }
[class*="side_"] [class*="item_"]:hover { background: rgba(230,177,63,.12) !important; }
[class*="side_"] [class*="selected_"] { background: rgba(47,182,255,.16) !important; color: var(--eg-gold-hi) !important; box-shadow: inset 3px 0 0 var(--eg-lapis); }
[class*="title_"][class*="eyebrow"], [class*="header_"][class*="sidebar"] { font-family: var(--eg-font-head); color: var(--eg-gold-hi); }
[class*="closeButton_"] { border-color: var(--eg-gold) !important; color: var(--eg-gold) !important; }

/* Buttons & inputs */
[class*="lookFilled_"][class*="colorBrand_"] {
  background: linear-gradient(180deg, #e6b13f, #9a650d) !important; color: #1a1204 !important;
  border: 1px solid #ffd97a; font-weight: 700; box-shadow: 0 0 12px rgba(230,177,63,.35);
}
[class*="lookFilled_"][class*="colorBrand_"]:hover { background: linear-gradient(180deg, #ffd97a, #b57a14) !important; }
input[class*="inputDefault_"], textarea[class*="textArea_"][class*="input"], [class*="input_"][class*="inputDefault"] {
  background: rgba(5,6,10,.9) !important; border: 1px solid rgba(230,177,63,.45) !important; color: var(--eg-text) !important;
}
input[class*="inputDefault_"]:focus { border-color: var(--eg-lapis) !important; box-shadow: 0 0 10px rgba(47,182,255,.4); }

/* Tooltips */
[class*="tooltip_"] { background: #0b0d15 !important; border: 1px solid var(--eg-gold); color: var(--eg-gold-hi) !important; font-weight: 600; }
[class*="tooltipPointer_"] { border-top-color: var(--eg-gold) !important; }

/* ============================================================
   9. DIRECT MESSAGES
   ============================================================ */
[class*="privateChannels_"] { background: transparent !important; }
[class*="privateChannels_"] [class*="channel_"] [class*="interactive_"] {
  border: 1px solid rgba(230,177,63,.16); border-radius: 4px !important; margin-block: 2px;
  background: linear-gradient(90deg, rgba(20,24,38,.7), rgba(8,10,16,.55));
}
[class*="privateChannels_"] [class*="selected_"] { border-color: var(--eg-lapis); box-shadow: inset 0 0 14px rgba(47,182,255,.28); }
[class*="peopleColumn_"], [class*="container_"][class*="friends"] { background: transparent !important; }

/* ============================================================
   10. SCROLLBARS
   ============================================================ */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: rgba(0,0,0,.35); border-radius: 6px; }
::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, var(--eg-gold), var(--eg-gold-lo)) !important;
  border: 2px solid #05060a !important; border-radius: 6px !important;
}
::-webkit-scrollbar-thumb:hover { background: linear-gradient(180deg, var(--eg-gold-hi), var(--eg-gold)) !important; }

/* Selection */
::selection { background: rgba(47,182,255,.45); color: #fff; }
